// Unicode explanation:
/*
UTF-16 Code Units:
- JavaScript strings are UTF-16 encoded
- Each character is represented as 16-bit code units
- Some characters (like emoji with modifiers) require surrogate pairs (two 16-bit units)
- String.length counts these code units, not characters
- String indexing and charAt() work with these units

Unicode Code Points:
- Each character has a unique code point (number)
- Most common characters fit in one UTF-16 code unit
- Supplementary characters (like many emoji) require two UTF-16 code units (surrogate pairs)
- String.fromCharCode() and codePointAt() deal with these

User-Perceived Grapheme Clusters:
- What users perceive as a single character
- Can be a single code point, a base character + combining marks, or emoji sequences
- Examples: "é" = "e" + combining acute accent, "👨‍👩‍👧‍👦" = multiple emoji joined with ZWJ
- Intl.Segmenter can properly identify these boundaries
- Without proper handling, our function would count surrogate pairs or combining marks separately
*/

// Implementation using Intl.Segmenter for grapheme clusters
function longestSubstringGrapheme(s) {
    if (typeof Intl === 'undefined' || !Intl.Segmenter) {
        console.warn("Intl.Segmenter not supported. Falling back to code unit counting.");
        return longestSubstring(s);
    }

    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    const segments = segmenter.segment(s);
    const graphemes = Array.from(segments).map(segment => segment.segment);

    let maxLength = 0;
    let left = 0;
    const graphemeIndexMap = new Map();

    for (let right = 0; right < graphemes.length; right++) {
        const currentGrapheme = graphemes[right];

        if (graphemeIndexMap.has(currentGrapheme) && graphemeIndexMap.get(currentGrapheme) >= left) {
            left = graphemeIndexMap.get(currentGrapheme) + 1;
        }

        graphemeIndexMap.set(currentGrapheme, right);
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}

