    // Test with combining marks
    const eCombining = "e\u0301e\u0302"; // "éè"
    console.log(longestSubstring(eCombining) === 2); // Counts as 2 code units
    console.log(longestSubstringGrapheme(eCombining) === 1); // Counts as 1 grapheme cluster

